node -e '
const fs=require("fs");
const {parseExport}=require("./src/import.js");
const {listEntries}=require("./src/store.js");

const raw=fs.readFileSync("data/export-2026-09-08.txt","utf8");
// 独立于解析器数一遍分隔符块，防止解析器静默丢块
const rawBlocks=raw.split(/\r?\n/).slice(2).join("\n").split("----------").map(s=>s.trim()).filter(s=>s.length>0);
const {entries,revoked}=parseExport(raw);
console.log("导出文件原始块数(按分隔符):",rawBlocks.length);
console.log("解析器识别:笔记",entries.length,"+ 撤销",revoked.length,"=",entries.length+revoked.length);

const all=listEntries("data/entries.jsonl");
console.log("库存总条数:",all.length);

// 逐条核对：导出的每条笔记是否在库存中有完全一致的 book/author/time/text
console.log("\n--- 逐条比对 ---");
let missing=0;
for(const e of entries){
  const hit=all.filter(a=>a.book===e.book&&a.author===e.author&&a.time===e.time&&a.text===e.text);
  console.log((hit.length===1?"OK  ":hit.length===0?"缺失":"重复"), hit.map(h=>h.id).join(",")||"-", e.book, e.time, JSON.stringify(e.text));
  if(hit.length!==1) missing++;
}
for(const r of revoked){
  const hit=all.filter(a=>a.book===r.book&&a.time===r.time);
  console.log(hit.length===0?"OK  已按规则跳过(未入库)":"异常 撤销条竟然入库了", r.book, r.time);
}
console.log("\n比对不一致条数:",missing);

// id 连续性 / 唯一性
const ids=all.map(a=>a.id);
console.log("id 唯一:",new Set(ids).size===ids.length, "| id 连续:",ids.every((id,i)=>id==="entry-"+String(i+1).padStart(4,"0")));

// 每本书条数
console.log("\n--- 每本书笔记条数 ---");
const byBook=new Map();
for(const a of all){const k=a.book+" "+a.author;byBook.set(k,(byBook.get(k)||0)+1);}
for(const [k,v] of [...byBook].sort((a,b)=>b[1]-a[1])) console.log(String(v).padStart(3),"条 ",k);
'
